INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ignoriere ich hier das Feedback der Nutzer?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzerinput ist zentral"}, {"text": "Ja", "correct": false, "because": "Rückmeldungen werden gesammelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt wähle ich, um Nutzer einzubeziehen?', 3, '[{"text": "Nutzer einbinden", "correct": true, "because": "Direkte Beteiligung"}, {"text": "Rückmeldungen sammeln", "correct": false, "because": "Folgt Einbindung"}, {"text": "Ignorieren", "correct": false, "because": "Feedback nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum Feedback-Prozess?', 5, '[{"text": "Nutzer einbinden", "correct": true, "because": "Input direkt erhalten"}, {"text": "Rückmeldungen sammeln", "correct": true, "because": "Verbesserungen identifizieren"}, {"text": "Nutzer ausschließen", "correct": false, "because": "Einbindung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Nutzerfeedback verbessert das Produkt. b) Rückmeldungen sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rückmeldungen essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei diesem Feedback-Ansatz?', 4, '[{"text": "Nutzer einbinden", "correct": false, "because": "Kern des Prozesses"}, {"text": "Rückmeldungen sammeln", "correct": false, "because": "Basis für Verbesserung"}, {"text": "Nutzerignoranz", "correct": true, "because": "Einbindung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier ohne Nutzerinput arbeite?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzer einbinden ist Schlüssel"}, {"text": "Ja", "correct": false, "because": "Feedback nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um Verbesserungen zu finden?', 3, '[{"text": "Rückmeldungen sammeln", "correct": true, "because": "Nutzerinput auswerten"}, {"text": "Nutzer einbinden", "correct": false, "because": "Vor Sammeln"}, {"text": "Zufällige Änderungen", "correct": false, "because": "Feedback-basiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte fördern Nutzer-orientierte Entwicklung?', 5, '[{"text": "Nutzer einbinden", "correct": true, "because": "Direkte Rückmeldung"}, {"text": "Rückmeldungen sammeln", "correct": true, "because": "Verbesserungen planen"}, {"text": "Nutzer ignorieren", "correct": false, "because": "Einbindung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Nutzer werden eingebunden. b) Feedback wird ignoriert. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Feedback wird genutzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Nutzer einbinden", "correct": false, "because": "Input direkt erhalten"}, {"text": "Rückmeldungen sammeln", "correct": false, "because": "Verbesserungen identifizieren"}, {"text": "Nutzer ausschließen", "correct": true, "because": "Einbindung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Feedback hier einmalig?', 2, '[{"text": "Nein", "correct": true, "because": "Iterativ gesammelt"}, {"text": "Ja", "correct": false, "because": "Fortlaufender Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente verbessern das Produkt?', 4, '[{"text": "Nutzer einbinden", "correct": true, "because": "Reale Bedürfnisse erkennen"}, {"text": "Rückmeldungen sammeln", "correct": true, "because": "Anpassungen planen"}, {"text": "Feedback ignorieren", "correct": false, "because": "Verbesserung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Nutzer hier keine Rolle spielen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzer einbinden ist Kern"}, {"text": "Ja", "correct": false, "because": "Feedback zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für besseres Feedback?', 3, '[{"text": "Nutzer einbinden", "correct": true, "because": "Direkte Rückmeldung"}, {"text": "Rückmeldungen sammeln", "correct": false, "because": "Folgt Einbindung"}, {"text": "Nutzer meiden", "correct": false, "because": "Input nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Rückmeldungen führen zu Verbesserungen. b) Nutzer werden ignoriert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nutzer einbinden zählt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat dieser Feedback-Ansatz?', 5, '[{"text": "Bessere Anpassung", "correct": true, "because": "Nutzerinput nutzen"}, {"text": "Relevante Verbesserungen", "correct": true, "because": "Rückmeldungen auswerten"}, {"text": "Nutzerferne", "correct": false, "because": "Einbindung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Nutzer einbinden", "correct": false, "because": "Kern des Prozesses"}, {"text": "Rückmeldungen sammeln", "correct": false, "because": "Basis für Verbesserung"}, {"text": "Feedback vermeiden", "correct": true, "because": "Input essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Nutzerinput hier unwichtig?', 3, '[{"text": "Nein", "correct": true, "because": "Feedback treibt Verbesserung"}, {"text": "Ja", "correct": false, "because": "Nutzer einbinden zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier einmalig Feedback hole?', 2, '[{"text": "Nein", "correct": true, "because": "Iterativ gesammelt"}, {"text": "Ja", "correct": false, "because": "Fortlaufend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt wähle ich nach der Einbindung?', 4, '[{"text": "Rückmeldungen sammeln", "correct": true, "because": "Input auswerten"}, {"text": "Nutzer einbinden", "correct": false, "because": "Schon geschehen"}, {"text": "Feedback ignorieren", "correct": false, "because": "Verbesserung nötig"}]');
